You are an independent READ-ONLY adversarial c02 reviewer. REQUIRED: do NOT invoke any tools, execute code, delegate, or read files. Your entire evidence set is reproduced below. Analyze only it and return your final review as prose.

At the VERY TOP: HEADLINE (PASS only if no blocker), CONTRADICTS, NOT FOUND, BLOCKER. Cite supplied file:line for every affirmative claim. A review with no contradiction search is a failure.

Check: default-off config reaches core; predicate requires explicit replacement verb plus durable artifact and respects mode precedence; core uses current user turn; injection telemetry records trigger reason; corpus 4/4 and 3 prompts; schedule 48 ordered OFF/ON repeats; behavioral failures do not suppress repeats; preflight checks sources/corpus/contract/review before materializing; raw capture/ledger is complete; contract covers behavior-defining files. State any defect as BLOCKER.

===== index.ts =====
1: // pi-ai-consortium entrypoint
2: // Deliberation layer: multiple models probe before the agent answers.
3: //
4: // Architecture B: input starts async deliberation, context awaits & injects.
5: 
6: // Custom session entry type — persists deliberation in session JSONL
7: // so both user (session replay) and agent can see what guidance was given.
8: const CUSTOM_TYPE = "pi-ai-consortium";
9: 
10: import type {
11:   ExtensionAPI,
12:   ExtensionContext,
13:   InputEvent,
14:   ContextEvent,
15:   TurnStartEvent,
16: } from "@earendil-works/pi-coding-agent";
17: import type { AgentMessage } from "@earendil-works/pi-agent-core";
18: import { ConsortiumCore, type ModelCallFn } from "./src/core.js";
19: import { callModelWithAuth } from "./src/model.js";
20: import { DEFAULT_CONFIG, parseModelRef } from "./src/config.js";
21: import { buildUserContext, buildUserContextFromMessages } from "./src/context.js";
22: import { ConsortiumLogger, createProgressCallback, formatVisibleMessage } from "./src/ui.js";
23: import type { ConsortiumConfig, TurnState, DeliberationResult, GovernorMode, TelemetryEvent } from "./src/types.js";
24: import { createUsageAccumulator, buildDeliberationTelemetry, safeLog } from "./src/telemetry.js";
25: import { join, dirname } from "node:path";
26: import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
27: import { existsSync } from "node:fs";
28: 
29: export default function (pi: ExtensionAPI): void {
30:   let enabled = true;
31:   let governorMode: GovernorMode = "smart_extractor";
32:   let maxTurnGap = 20;
33:   let periodicInterval = 10;
34:   let stateSupersessionGuard = false;
35:   let turnsSinceLastAudit = 0;
36: 
37:   let turnState: TurnState = { deliberation: null };
38:   let lastExtractedContext: DeliberationResult["extractedContext"] | null = null;
39:   let logger: ConsortiumLogger | null = null;
40: 
41:   // Queue writes sequentially to prevent race conditions between rapid toggles.
42:   let persistPending: Promise<void> = Promise.resolve();
43: 
44:   async function persistSettings(
45:     cwd: string,
46:     opts: { enabled?: boolean; governorMode?: GovernorMode; maxTurnGap?: number; periodicInterval?: number; stateSupersessionGuard?: boolean },
47:   ): Promise<void> {
48:     persistPending = persistPending.then(async () => {
49:       try {
50:         const dir = join(cwd, ".pi");
51:         try {
52:           await mkdir(dir, { recursive: true });
53:         } catch {
54:           // Directory exists or mkdir failed.
55:         }
56:         const p = join(dir, "settings.json");
57:         const tmp = p + ".tmp";
58:         let s: Record<string, unknown> = {};
59:         if (existsSync(p)) {
60:           try {
61:             const raw = await readFile(p, "utf-8");
62:             s = JSON.parse(raw);
63:           } catch {
64:             // Corrupted file — overwrite.
65:           }
66:         }
67: 
68:         let existingConsortium: Record<string, unknown> = {};
69:         if (typeof s.consortium === "object" && s.consortium !== null) {
70:           existingConsortium = s.consortium as Record<string, unknown>;
71:         } else if (typeof s.consortium === "boolean") {
72:           existingConsortium = { enabled: s.consortium };
73:         }
74: 
75:         s.consortium = {
76:           enabled: opts.enabled !== undefined ? opts.enabled : (existingConsortium.enabled ?? enabled),
77:           governorMode: opts.governorMode !== undefined ? opts.governorMode : (existingConsortium.governorMode ?? governorMode),
78:           maxTurnGap: opts.maxTurnGap !== undefined ? opts.maxTurnGap : (existingConsortium.maxTurnGap ?? maxTurnGap),
79:           periodicInterval: opts.periodicInterval !== undefined ? opts.periodicInterval : (existingConsortium.periodicInterval ?? periodicInterval),
80:           stateSupersessionGuard: opts.stateSupersessionGuard !== undefined ? opts.stateSupersessionGuard : (existingConsortium.stateSupersessionGuard ?? stateSupersessionGuard),
81:         };
82: 
83:         await writeFile(tmp, JSON.stringify(s, null, 2) + "\n");
84:         await rename(tmp, p);
85:       } catch {
86:         // Best-effort persistence.
87:       }
88:     });
89:     await persistPending;
90:   }
91: 
92:   pi.on("session_start", async (_event, ctx) => {
93:     try {
94:       const p = join(ctx.cwd, ".pi", "settings.json");
95:       if (!existsSync(p)) return;
96:       const raw = await readFile(p, "utf-8");
97:       const s = JSON.parse(raw);
98:       if (typeof s.consortium === "boolean") {
99:         enabled = s.consortium;
100:       } else if (typeof s.consortium === "object" && s.consortium !== null) {
101:         if (s.consortium.enabled !== undefined) enabled = !!s.consortium.enabled;
102:         if (s.consortium.governorMode !== undefined) governorMode = s.consortium.governorMode as GovernorMode;
103:         if (typeof s.consortium.maxTurnGap === "number") maxTurnGap = s.consortium.maxTurnGap;
104:         if (typeof s.consortium.periodicInterval === "number") periodicInterval = s.consortium.periodicInterval;
105:         if (typeof s.consortium.stateSupersessionGuard === "boolean") stateSupersessionGuard = s.consortium.stateSupersessionGuard;
106:       }
107:       if (!enabled && ctx.hasUI) {
108:         ctx.ui.setStatus("consortium", "consortium: disabled");
109:       }
110:     } catch {
111:       // Default to enabled — fail open for safety.
112:     }
113:   });
114: 
115:   pi.on("turn_start", (_event: TurnStartEvent) => {
116:     // Only reset if no in-flight deliberation (turn_start fires after input but before context)
117:     if (!turnState.deliberation) {
118:       turnState = { deliberation: null };
119:     }
120:   });
121: 
122:   pi.on("input", async (event: InputEvent, ctx: ExtensionContext) => {
123:     const userContext = buildUserContext(event, ctx);
124: 
125:     // Initialize logger once per session
126:     if (!logger) {
127:       logger = new ConsortiumLogger(ctx.cwd, ctx.sessionManager.getSessionId());
128:     }
129:     logger.log({ type: "turn_start", input: userContext });
130: 
131:     return { action: "continue" };
132:   });
133: 
134:   // On first LLM call of the turn, await deliberation and inject.
135:   pi.on("context", async (event: ContextEvent, ctx: ExtensionContext) => {
136:     if (!enabled) {
137:       if (ctx.hasUI) {
138:         ctx.ui.setStatus("consortium", "consortium: disabled");
139:       }
140:       return;
141:     }
142:     if (turnState.deliberation) {
143:       return;
144:     }
145: 
146:     const userContext = buildUserContextFromMessages(event.messages);
147:     if (!userContext) {
148:       return;
149:     }
150: 
151:     if (!logger) {
152:       logger = new ConsortiumLogger(ctx.cwd, ctx.sessionManager.getSessionId());
153:     }
154: 
155:     const onProgress = createProgressCallback(ctx);
156:     const runtimeConfig = {
157:       ...DEFAULT_CONFIG,
158:       governorMode,
159:       maxTurnGap,
160:       periodicInterval,
161:       stateSupersessionGuard,
162:     };
163: 
164:     turnState.deliberation = runDeliberation(runtimeConfig, event.messages, ctx, logger, onProgress, turnsSinceLastAudit, lastExtractedContext !== null);
165: 
166:     try {
167:       const result = await turnState.deliberation;
168: 
169:       if (result.skippedByGovernor) {
170:         turnState.deliberation = null;
171:         lastExtractedContext = result.extractedContext ?? null;
172:         turnsSinceLastAudit++;
173:         if (result.extractedContext) {
174:           logger?.logExtraction(result.extractedContext);
175:         }
176:         logger?.log({
177:           type: "injection_skipped",
178:           reason: result.governorReason || "SKIPPED_BY_GOVERNOR",
179:           probe_count: 0,
180:           extractedContext: result.extractedContext,
181:         });
182:         if (ctx.hasUI) {
183:           ctx.ui.setStatus("consortium", "consortium: ⏭ skipped");
184:           ctx.ui.notify(formatVisibleMessage(result), "info");
185:         }
186:         return;
187:       }
188: 
189:       // Full probe audit ran — reset turn counter gap
190:       turnsSinceLastAudit = 0;
191: 
192:       if (result.synthesis.trim().startsWith("NO_CONTRIBUTION")) {
193:         turnState.deliberation = null;
194:         lastExtractedContext = result.extractedContext ?? null;
195:         if (result.extractedContext) {
196:           logger?.logExtraction(result.extractedContext);
197:         }
198:         logger?.log({
199:           type: "injection_skipped",
200:           reason: "NO_CONTRIBUTION",
201:           probe_count: result.probes.length,
202:           extractedContext: result.extractedContext,
203:         });
204:         if (ctx.hasUI) {
205:           ctx.ui.setStatus("consortium", "consortium: ✓ complete (nothing to add)");
206:           ctx.ui.notify(formatVisibleMessage(result), "info");
207:         }
208:         return;
209:       }
210: 
211:       const syntheticMessage: AgentMessage = {
212:         role: "user",
213:         content: `[CONSORTIUM DELIBERATION]\n\n${result.synthesis}`,
214:         timestamp: Date.now(),
215:       };
216: 
217:       const messages = [...event.messages];
218:       messages.push(syntheticMessage);
219:       turnState.deliberation = null;
220:       lastExtractedContext = result.extractedContext ?? null;
221:       if (result.extractedContext) {
222:         logger?.logExtraction(result.extractedContext);
223:       }
224: 
225:       logger?.log({
226:         type: "injection_complete",
227:         synthesis_length: result.synthesis.length,
228:         probe_count: result.probes.length,
229:         errors: result.errors,
230:         governor_reason: result.governorReason,
231:         probes: result.probes,
232:         synthesis: result.synthesis,
233:         extractedContext: result.extractedContext,
234:       });
235: 
236:       // Persist in session JSONL
237:       try {
238:         pi.appendEntry(CUSTOM_TYPE, {
239:           schemaVersion: "0.1",
240:           kind: "deliberation",
241:           synthesis: result.synthesis,
242:           probe_count: result.probes.length,
243:           extractedContext: result.extractedContext,
244:           errors: result.errors,
245:         });
246:       } catch {
247:         // Some modes don't support session append.
248:       }
249: 
250:       // Visible TUI notification
251:       if (ctx.hasUI) {
252:         ctx.ui.notify(formatVisibleMessage(result), result.errors?.length ? "warning" : "info");
253:       }
254: 
255:       if (result.errors) {
256:         if (ctx.hasUI) {
257:           ctx.ui.setStatus("consortium", `consortium: ⚠ ${result.errors.length} error(s)`);
258:         }
259:       } else {
260:         if (ctx.hasUI) {
261:           ctx.ui.setStatus("consortium", "consortium: ✓ complete");
262:         }
263:       }
264: 
265:       return { messages };
266:     } catch (err) {
267:       const msg = err instanceof Error ? err.message : String(err);
268:       logger?.log({ type: "deliberation_failed", error: msg });
269:       if (ctx.hasUI) {
270:         ctx.ui.setStatus("consortium", `consortium: ✖ failed: ${msg}`);
271:       }
272:       turnState.deliberation = null;
273:       return;
274:     }
275:   });
276: 
277:   pi.registerCommand("ai-consortium", {
278:     description: "Show consortium deliberation status and governor mode",
279:     handler: async (_args, ctx) => {
280:       const deliberationModel = resolveDeliberationModel(ctx);
281:       const info = [
282:         `Consortium: ${enabled ? "enabled" : "disabled"}`,
283:         `Deliberation Model: ${deliberationModel.provider}/${deliberationModel.id} (${deliberationModel.source})`,
284:         `Governor Mode: ${governorMode}`,
285:         `Max Turn Gap (Safety Net): ${maxTurnGap}`,
286:         `Periodic Interval: ${periodicInterval}`,
287:         `Turns Since Last Full Audit: ${turnsSinceLastAudit}`,
288:       ].join("\n");
289:       ctx.ui.notify(info, "info");
290:     },
291:   });
292: 
293:   pi.registerCommand("ai-consortium-on", {
294:     description: "Enable consortium deliberation",
295:     handler: async (_args, ctx) => {
296:       enabled = true;
297:       await persistSettings(ctx.cwd, { enabled: true });
298:       if (ctx.hasUI) {
299:         ctx.ui.setStatus("consortium", undefined);
300:       }
301:       ctx.ui.notify("Consortium enabled", "info");
302:     },
303:   });
304: 
305:   pi.registerCommand("ai-consortium-off", {
306:     description: "Disable consortium deliberation",
307:     handler: async (_args, ctx) => {
308:       enabled = false;
309:       await persistSettings(ctx.cwd, { enabled: false });
310:       if (ctx.hasUI) {
311:         ctx.ui.setStatus("consortium", "consortium: disabled");
312:       }
313:       ctx.ui.notify("Consortium disabled", "info");
314:     },
315:   });
316: 
317:   pi.registerCommand("ai-consortium-cadence", {
318:     description: "Set governor cadence mode: smart_extractor | always | periodic [N] | manual",
319:     handler: async (args, ctx) => {
320:       const parts = args.trim().split(/\s+/);
321:       const mode = parts[0]?.toLowerCase() as GovernorMode | undefined;
322: 
323:       if (!mode || !["smart_extractor", "always", "periodic", "manual"].includes(mode)) {
324:         ctx.ui.notify("Usage: /ai-consortium-cadence <smart_extractor | always | periodic [N] | manual>", "warning");
325:         return;
326:       }
327: 
328:       governorMode = mode;
329:       let newInterval = periodicInterval;
330:       if (mode === "periodic" && parts[1] && !isNaN(parseInt(parts[1], 10))) {
331:         newInterval = parseInt(parts[1], 10);
332:         periodicInterval = newInterval;
333:       }
334: 
335:       await persistSettings(ctx.cwd, { governorMode, periodicInterval: newInterval });
336:       ctx.ui.notify(`Governor mode set to: ${governorMode}${governorMode === "periodic" ? ` (${periodicInterval} turns)` : ""}`, "info");
337:     },
338:   });
339: 
340:   pi.registerCommand("ai-consortium-context", {
341:     description: "Inspect the last turn's 9 extracted strategic context vectors",
342:     handler: async (_args, ctx) => {
343:       if (!lastExtractedContext) {
344:         ctx.ui.notify("No extracted context available yet for this session.", "info");
345:         return;
346:       }
347:       const fmt = (items?: string[]) => (!items || items.length === 0 ? "[none]" : items.join("; "));
348:       const summary = [
349:         `◇ Extracted 9 Strategic Context Vectors:`,
350:         `  • User Requirements: ${fmt(lastExtractedContext.userRequirements)}`,
351:         `  • Deliverables: ${fmt(lastExtractedContext.deliverables)}`,
352:         `  • Revised / Superseded: ${fmt(lastExtractedContext.revisedOrSupersededDirection)}`,
353:         `  • User Decisions: ${fmt(lastExtractedContext.userDecisions)}`,
354:         `  • Questions & Info Gaps: ${fmt(lastExtractedContext.questionsAndInformationGaps)}`,
355:         `  • Control Boundaries: ${fmt(lastExtractedContext.controlBoundaries)}`,
356:         `  • Observed Work: ${fmt(lastExtractedContext.observedWork)}`,
357:         `  • Observed Critical Facts: ${fmt(lastExtractedContext.observedCriticalFacts)}`,
358:         `  • Relevant Learnings: ${fmt(lastExtractedContext.relevantLearnings)}`,
359:       ].join("\n");
360: 
361:       ctx.ui.notify(summary, "info");
362:     },
363:   });
364: }
