39: /** Configuration for a single probe role. */
40: export interface ProbeConfig {
41:   /** Role name (displayed in logs). */
42:   role: string;
43:   /** System prompt for this probe. Shared across all probes for KV-prefix cache reuse. */
44:   systemPrompt: string;
45:   /** Role-specific lens appended to the user message tail.
46:    * Contains the gate criteria and severity definitions unique to this role.
47:    * Placed at the tail so it does not break the shared prefix cache. */
48:   roleLens: string;
