74: def continuity_passes(fixture: Dict[str, Any], final_text: str) -> bool:
75:     if fixture.get("kind") != "positive":
76:         return True
77:     lower = final_text.lower()
78:     current = all(marker.lower() in lower for marker in fixture.get("current_markers", []))
79:     historical = all(
80:         marker.lower() in lower and any(word in lower[max(0, lower.find(marker.lower()) - 100): lower.find(marker.lower()) + len(marker) + 100] for word in ("supersed", "histor", "replac", "former", "previous", "retired", "migrated"))
81:         for marker in fixture.get("historical_markers", [])
82:     )
83:     return current and historical
