86: def verify_contract(expected_sha256: str) -> Dict[str, Any]:
87:     if sha256_file(CONTRACT_PATH) != expected_sha256:
88:         raise RuntimeError("c02 contract SHA-256 mismatch")
89:     data = json.loads(CONTRACT_PATH.read_text())
90:     if data.get("schema_version") != "c02-contract-files-v1" or not isinstance(data.get("files"), list):
91:         raise RuntimeError("c02 contract schema invalid")
92:     paths: set[str] = set()
93:     for item in data["files"]:
94:         if not isinstance(item, dict) or set(item) != {"path", "sha256"}:
95:             raise RuntimeError("c02 contract entry invalid")
96:         rel = item["path"]
97:         if not isinstance(rel, str) or rel in paths or rel.startswith("/") or ".." in Path(rel).parts:
98:             raise RuntimeError("c02 contract path invalid")
99:         paths.add(rel)
100:         target = REPO_ROOT / rel
101:         if not target.is_file() or sha256_file(target) != item["sha256"]:
102:             raise RuntimeError(f"c02 contract file mismatch: {rel}")
103:     if not paths:
104:         raise RuntimeError("c02 contract has no files")
105:     return data
